#include <stddef.h>

size_t my_strlen(const char *s) {
    const char *p = s;
    while (*p != '\0') p++;       // stop at the terminator
    return (size_t)(p - s);        // pointer difference, in chars
}

char *my_strcpy(char *dst, const char *src) {
    char *d = dst;
    while ((*d++ = *src++) != '\0')
        ;                          // copies the terminator, then stops
    return dst;                    // caller must have sized dst >= len+1
}

int my_strcmp(const char *a, const char *b) {
    while (*a && *a == *b) { a++; b++; }
    return (unsigned char)*a - (unsigned char)*b;   // <0, 0, >0
}

