void reverse(char *s) {
    size_t n = strlen(s);
    if (n < 2) return;
    for (size_t i = 0, j = n - 1; i < j; i++, j--) {
        char t = s[i]; s[i] = s[j]; s[j] = t;
    }
}
int is_palindrome(const char *s) {
    size_t i = 0, j = strlen(s);
    while (j > i + 1) if (s[i++] != s[--j]) return 0;
    return 1;
}
